function getStudentById(studentId) {
  return getAllStudents().find(s => s.id === studentId) || null;
}

function getStudentByEmail(email) {
  return getAllStudents().find(s => s.email.toLowerCase() === String(email).toLowerCase()) || null;
}

function initials(name) {
  return name.split(" ").map(p => p[0]).join("").slice(0, 2).toUpperCase();
}

/* ==========================================================================
   Registration support
   Newly registered students are stored separately in localStorage (never
   mutating the built-in STUDENTS array) and merged in at lookup time, so
   the seeded demo roster stays stable across sessions while new sign-ups
   persist. New students start with no quiz history — an intentional
   "empty state" until they take their first quiz.
   ========================================================================== */
function getCustomStudents() {
  try {
    const raw = localStorage.getItem("aelp_custom_students");
    return raw ? JSON.parse(raw) : [];
  } catch (e) {
    return [];
  }
}

function getAllStudents() {
  return STUDENTS.concat(getCustomStudents());
}

function isStudentIdTaken(id) {
  return getAllStudents().some(s => s.id.toUpperCase() === String(id).toUpperCase());
}

/** Login can use either the registered email or the generated Student ID. */
function findStudentForLogin(identifier) {
  const val = String(identifier || "").trim();
  if (!val) return null;
  if (val.includes("@")) return getStudentByEmail(val);
  return getAllStudents().find(s => s.id.toLowerCase() === val.toLowerCase()) || null;
}

function registerStudent({ schoolName, name, rollNumber, password, subjects }) {
  const id = generateStudentId(schoolName, rollNumber);
  if (isStudentIdTaken(id)) {
    return { ok: false, error: "duplicate", id };
  }
  const record = {
    id,
    name,
    email: id.toLowerCase() + "@edunexus.local",
    password,
    subjects: subjects && subjects.length ? subjects : SET_A,
    tier: "new",
    schoolName,
  };
  const custom = getCustomStudents();
  custom.push(record);
  localStorage.setItem("aelp_custom_students", JSON.stringify(custom));
  return { ok: true, id, record };
}

/** [SCHOOL CODE][ROLL NUMBER] — school code is the first 4 letters of the school name, uppercased and padded if short. */
function generateStudentId(schoolName, rollNumber) {
  const code = schoolCode(schoolName);
  const roll = String(rollNumber).trim().replace(/\s+/g, "");
  return code + roll;
}

function schoolCode(schoolName) {
  const letters = String(schoolName || "").toUpperCase().replace(/[^A-Z]/g, "");
  if (letters.length >= 4) return letters.slice(0, 4);
  return (letters + "XXXX").slice(0, 4);
}

window.STUDENTS = STUDENTS;
window.getStudentById = getStudentById;
window.getStudentByEmail = getStudentByEmail;
window.initials = initials;
window.getCustomStudents = getCustomStudents;
window.getAllStudents = getAllStudents;
window.isStudentIdTaken = isStudentIdTaken;
window.findStudentForLogin = findStudentForLogin;
window.registerStudent = registerStudent;
window.generateStudentId = generateStudentId;
window.schoolCode = schoolCode;
window.SET_A = SET_A;
window.SET_B = SET_B;
window.SET_C = SET_C;
